import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, uv, texture, mul, add, mix, fract, sin, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load the main image texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  imageTexture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with aspect ratio from atlas region
  // Atlas region 512x320 → aspect 1.6
  const aspectRatio = 512 / 320;
  const height = 2.0;
  const width = height * aspectRatio;

  const geometry = new THREE.PlaneGeometry(width, height);

  // Build TSL material with engineered gradient and subtle grain
  const uvNode = uv();

  // Sample main texture
  const mainTexNode = texture(imageTexture, uvNode);

  // Engineered gradient overlay (vertical fade for depth)
  const gradientFade = mix(
    vec3(1.0, 1.0, 1.0),
    vec3(0.97, 0.97, 0.97),
    uvNode.y
  );
  const textureWithGradient = mul(mainTexNode, gradientFade);

  // Procedural grain using sine-based pattern
  const grainPattern = fract(
    add(
      sin(mul(uvNode.x, 43.0)),
      sin(mul(uvNode.y, 73.0))
    )
  );
  const grainOverlay = mul(grainPattern, 0.02);

  // Composite: gradient-modulated texture + grain
  const finalColor = add(textureWithGradient, grainOverlay);

  const material = new MeshBasicNodeMaterial({
    colorNode: finalColor,
    transparent: true
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  mesh.position.set(0, -2.85, 0.2);
  mesh.rotation.order = 'XYZ';
  mesh.scale.set(1, 1, 1);

  group.add(mesh);

  // Cleanup resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
